        tcp=s.env.tcp_center
        obj=s.state()['object_pos']
        if obj[0]>=goal[0]-params['switch_dist']:
            touched=True;break
        s.step([params['speed'],np.clip(params['push_gain']*(goal[1]+params['yoffset']-tcp[1]),-1,1),
                np.clip(params['push_gain']*(params['height']-tcp[2]),-1,1),params['grip']])
    if touched:
        move([goal[0]-params['end_offset'],goal[1]+params['end_yoffset'],params['height']],params['settle_steps'],params['end_gain'])
    if params.get('withdraw',0):
        for i in range(params['withdraw']):
            s.step([-params.get('withdraw_speed',.5),0,0,params['grip']])
    main_len=len(s.actions)
    st=s.state();main_actions=np.array(s.actions)
    result=dict(params=params,steps=main_len,success=st['success'],distance=st['obj_to_target'],
                object=st['object_pos'].tolist(),velocity=s.data.qvel[-6:].tolist())
    if log:print(json.dumps(result),flush=True)
    if main_len<=500 and result['success']:
